python3 - <<'PY'
import openpyxl
from openpyxl.utils import get_column_letter
wb=openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']
# search for year 2018 etc in first 60 rows and columns A-T
years={2018,2019,2020,2021,2022}
found=[]
for r in range(1,61):
    for c in range(1,31):
        v=ws.cell(r,c).value
        if v in years:
            found.append((v,r,get_column_letter(c)))

print('Found year cells:', found)

# print rows 1-25 for columns A-N trimmed
for r in range(1,26):
    vals=[ws[f'{get_column_letter(c)}{r}'].value for c in range(1,15)]
    if any(v is not None for v in vals):
        print(f'Row {r} A-N:', vals)
